-- Royal Nuts launch catalog. Run after schema.sql to create inactive, zero-stock drafts.
-- Review the supplier grade, label, actual landed costs and packed inventory before activation.
-- Existing product IDs and slugs are preserved. This does not update active listings.
-- PKR target ingredient costs per kg: premium-almonds 3200, premium-cashews 3600, roasted-pistachios 4300, salted-pistachios 4400, premium-walnuts 2800, aseel-dates 1000, ajwa-dates 4200, mabroom-dates 4000, golden-raisins 1700, roasted-peanuts 1300, dried-figs 3500, mixed-dry-fruits 1880.
-- Cost formula: round up to Rs 10 after (ingredient cost x 1.03 + packing/handling) / 0.85.
-- Packet packing/handling assumptions: Rs 30/35/45 for 100/250/500 g. Delivery is separate.
-- Gift box materials and handling assumptions: Rs 125 parents, Rs 85 family, Rs 105 fruit.
-- Source benchmarks: https://dryfruitsmart.pk/dry-fruits-rates-in-karachi/
-- https://burushaskiorganics.com/pages/wholesale
-- https://www.naheed.pk/naheed-products/naheed-dry-fruits
-- https://alidryfruit.com/dry-fruits/dates/
begin;

insert into public.products (id, active, data)
select draft->>'id', false, draft
from jsonb_array_elements($catalog$
